                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.TUCO_KIDS_FINAL_SKU_MASTER; CREATE TABLE public.TUCO_KIDS_FINAL_SKU_MASTER AS with listing_mast as ( select * from ( select upper(Marketplace) MARKETPLACE ,upper(replace(\"Marketplace SKU\",\'`\',\'\')) MARKETPLACE_SKU ,upper(coalesce(replace(\"Master SKU\",\'`\',\'\'),replace(\"Marketplace SKU\",\'`\',\'\'))) COMMONSKU ,upper(replace(Identifier,\'`\',\'\')) SKU_IDENTIFIER ,upper(replace(Identifier1,\'`\',\'\')) SKU_IDENTIFIER1 ,upper(replace(Identifier2,\'`\',\'\')) SKU_IDENTIFIER2 ,upper(replace(ID,\'`\',\'\')) SKU_ID ,upper(title) Product_name ,row_number() over (partition by upper(marketplace),upper(replace(\"Marketplace SKU\",\'`\',\'\')) order by length(replace(\"Master SKU\",\'`\',\'\')) desc) as rw from public.unbottle_sku_listing_master ) where rw = 1 ), PRODUCT_MASTER AS ( SELECT upper(replace(SKU,\'`\',\'\')) COMMONSKU, Product_id, upper(product_name) PRODUCT_NAME, upper(category_name) CATEGORY, upper(product_type) PRODUCT_TYPE, upper(SIZE) SIZE, Upper(colour) COLOR, cast(cost as double precision) COST, cast(tax_rate as double precision) TAX_RATE, product_image_url, concat(\'<img src=\"\',concat(product_image_url,\'\"width=\"70\">\')) as Image, model_no, cast(active as int) as is_active, (cost::double precision) as cogs, (mrp::double precision) as mrp FROM public.Easyecom_Tuco_Kids_product_master ) select lm.marketplace_sku, lm.marketplace, pm.COMMONSKU, lm.SKU_ID as Marketplace_ID, pm.PRODUCT_ID, pm.PRODUCT_NAME, pm.CATEGORY, pm.product_type, pm.SIZE, pm.COLOR, pm.MRP, pm.COGS, pm.TAX_RATE, pm.image, pm.product_image_url from PRODUCT_MASTER pm left join listing_mast lm on lm.commonsku = pm.commonsku; DROP TABLE IF EXISTS public.tuco_kids_parent_child_sku_master; CREATE TABLE public.tuco_kids_parent_child_sku_master AS SELECT * FROM (WITH old_sku_normalisation AS ( SELECT * FROM ( SELECT easyecom AS easyecom_combo_sku, \"combo skus\" AS combo_SKU, ROW_NUMBER() OVER (PARTITION BY easyecom ORDER BY (CASE WHEN \"combo skus\" = easyecom THEN 2 ELSE 1 END) ASC, LENGTH(\"combo skus\") DESC) AS rw FROM public.unbottle_l1_combo_mapping ) WHERE rw = 1 ), PARENT_CHILD_MAPPING AS ( SELECT \"Parent SKU\", \"Child SKU\", \"Child Quantity\" FROM ( SELECT \"parent sku\" AS \"Parent SKU\", TRIM(SPLIT_PART(component, \'&\', 1)) AS \"Child SKU\", NULLIF(TRIM(SPLIT_PART(component, \'&\', 2)), \'\')::INT AS \"Child Quantity\" FROM ( SELECT \"parent sku\", CASE n.pos WHEN 1 THEN \"component 1 - sku\" WHEN 2 THEN \"component 2 - sku\" WHEN 3 THEN \"component 3 - sku\" WHEN 4 THEN \"component 4 - sku\" WHEN 5 THEN \"component 5 - sku\" WHEN 6 THEN \"component 6 - sku\" WHEN 7 THEN \"component 7 - sku\" WHEN 8 THEN \"component 8 - sku\" WHEN 9 THEN \"component 9 - sku\" WHEN 10 THEN \"component 10 - sku\" WHEN 11 THEN \"component 11 - sku\" WHEN 12 THEN \"component 12 - sku\" WHEN 13 THEN \"component 13 - sku\" WHEN 14 THEN \"component 14 - sku\" WHEN 15 THEN \"component 15 - sku\" WHEN 16 THEN \"component 16 - sku\" WHEN 17 THEN \"component 17 - sku\" WHEN 18 THEN \"component 18 - sku\" WHEN 19 THEN \"component 19 - sku\" WHEN 20 THEN \"component 20 - sku\" END AS component FROM public.unbottle_combo_sku_mapping CROSS JOIN ( SELECT 1 AS pos UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 ) n ) unpivoted WHERE component IS NOT NULL AND TRIM(component ) != \'\' AND component != \'NULL\' ) comp WHERE \"Child SKU\" != \"Parent SKU\" ), PRODUCT_MASTER AS ( SELECT * FROM ( SELECT upper(replace(SKU,\'`\',\'\')) COMMONSKU, Product_id, upper(product_name) PRODUCT_NAME, upper(category_name) CATEGORY, upper(product_type) PRODUCT_TYPE, product_image_url, concat(\'<img src=\"\',concat(product_image_url,\'\"width=\"70\">\')) as Image, row_number() over (partition by upper(replace(SKU,\'`\',\'\')) order by upper(replace(SKU,\'`\',\'\')) desc) as rw FROM public.Easyecom_Tuco_Kids_product_master ) t WHERE rw = 1 ) SELECT pm.PRODUCT_NAME as parent_product_name, pcm.\"Parent SKU\" as parent_sku, osn.combo_SKU as old_combo_sku, pcm.\"Child SKU\" as child_sku, pmc.PRODUCT_NAME as child_product_name, COALESCE(pcm.\"Child Quantity\", 1) as Child_Quantity, pmc.category as child_category, pmc.Image, pmc.product_image_url, pmc.product_type, ROW_NUMBER() OVER (PARTITION BY pcm.\"Parent SKU\", pcm.\"Child SKU\", osn.combo_SKU ORDER BY 1 DESC) AS RW FROM PARENT_CHILD_MAPPING pcm LEFT JOIN old_sku_normalisation osn ON osn.easyecom_combo_sku = pcm.\"Parent SKU\" LEFT JOIN PRODUCT_MASTER pmc ON pmc.commonsku = pcm.\"Child SKU\" LEFT JOIN PRODUCT_MASTER pm ON pm.commonsku = pcm.\"Parent SKU\" ) WHERE RW = 1;",
